using System;using System.IO;using UnityEngine;using UnityEditor;public static class C1Diagnose{public static void Run(){var a=RuinsLayout.Generate(123);var b=AdventureData.Clone(a);string root=ValidationStorage.Root(Environment.GetCommandLineArgs(),true);File.WriteAllText(root+"/before-clone.json",JsonUtility.ToJson(a,true));File.WriteAllText(root+"/after-clone.json",JsonUtility.ToJson(b,true));try{b.Validate();File.WriteAllText(root+"/outcome.txt","VALID");EditorApplication.Exit(0);}catch(Exception e){File.WriteAllText(root+"/outcome.txt",e+"\nterrainNull="+(b.terrain==null)+"\nfailuresNull="+(b.generationFailures==null));EditorApplication.Exit(1);}}}